import "dotenv/config";

export const isCloudflareWorker = (): boolean => {
  return process.env.RUNTIME_ENV === 'cloudflare-worker';
};

/**
 * Formats a date for database storage
 * Returns Date object when running on Express, or ISO string when running on Cloudflare Worker
 */
export const formatDateForDb = (date: Date | string | null): Date | string | null => {
  if (!date) return null;
  
  const dateObj = date instanceof Date ? date : new Date(date);
  
  if (isCloudflareWorker()) {
    // Return ISO string when running on Cloudflare Worker
    return dateObj.toISOString();
  }
  
  // Return Date object when running on Express
  return dateObj;
};

/**
 * Parses a date from the database
 * Always returns a Date object regardless of the input format
 */
export const parseDateFromDb = (date: string | Date | null): Date | null => {
  if (!date) return null;
  return date instanceof Date ? date : new Date(date);
};

/**
 * Formats a date for API responses
 * Always returns an ISO string for consistent API responses
 */
export const formatDateForResponse = (date: Date | string | null): string | null => {
  if (!date) return null;
  const dateObj = date instanceof Date ? date : new Date(date);
  return dateObj.toISOString();
};
